const html = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>이성호 | 자기소개</title>\n  <script>\n    (() => {\n      try {\n        const saved = localStorage.getItem(\"profile-theme\");\n        const systemDark = window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n        document.documentElement.dataset.theme = saved || (systemDark ? \"dark\" : \"light\");\n      } catch {\n        document.documentElement.dataset.theme = \"light\";\n      }\n    })();\n  </script>\n  <style>\n    :root {\n      --ink: #18212b;\n      --text: #4e5d6c;\n      --muted: #83909c;\n      --blue: #378fca;\n      --blue-soft: #e7f3fa;\n      --mint: #dff3ea;\n      --peach: #ffe9d9;\n      --paper: #ffffff;\n      --page: #f4f6f7;\n      --line: #dfe5e9;\n      color-scheme: light;\n    }\n\n    :root[data-theme=\"dark\"] {\n      --ink: #f1f6f9;\n      --text: #c2cdd4;\n      --muted: #8f9da7;\n      --blue: #62afe0;\n      --blue-soft: #17384b;\n      --mint: #193d35;\n      --peach: #4a3022;\n      --paper: #121a20;\n      --page: #0b1116;\n      --line: #29343c;\n      color-scheme: dark;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    html {\n      scroll-behavior: smooth;\n    }\n\n    body {\n      margin: 0;\n      color: var(--text);\n      background: var(--page);\n      font-family: \"Malgun Gothic\", \"Apple SD Gothic Neo\", Arial, sans-serif;\n      line-height: 1.65;\n    }\n\n    .page {\n      position: relative;\n      width: min(1120px, calc(100% - 36px));\n      margin: 24px auto;\n      background: var(--paper);\n      box-shadow: 0 16px 50px rgba(24, 33, 43, 0.07);\n    }\n\n    .toolbar {\n      position: absolute;\n      top: 22px;\n      right: 24px;\n      z-index: 10;\n      display: flex;\n      gap: 8px;\n      align-items: center;\n    }\n\n    .language-switch {\n      display: flex;\n      gap: 3px;\n      padding: 4px;\n      background: var(--paper);\n      border: 1px solid var(--line);\n      border-radius: 999px;\n    }\n\n    .language-button {\n      padding: 5px 8px;\n      color: var(--muted);\n      background: transparent;\n      border: 0;\n      border-radius: 999px;\n      font: inherit;\n      font-size: 0.7rem;\n      font-weight: 700;\n      cursor: pointer;\n    }\n\n    .language-button:hover {\n      color: var(--blue);\n    }\n\n    .language-button[aria-pressed=\"true\"] {\n      color: var(--paper);\n      background: var(--blue);\n    }\n\n    .language-button:focus-visible {\n      outline: 3px solid color-mix(in srgb, var(--blue) 35%, transparent);\n      outline-offset: 2px;\n    }\n\n    .theme-toggle {\n      display: inline-flex;\n      gap: 7px;\n      align-items: center;\n      padding: 8px 11px;\n      color: var(--text);\n      background: var(--paper);\n      border: 1px solid var(--line);\n      border-radius: 999px;\n      font: inherit;\n      font-size: 0.78rem;\n      font-weight: 700;\n      cursor: pointer;\n    }\n\n    .theme-toggle:hover {\n      color: var(--blue);\n      border-color: var(--blue);\n    }\n\n    .theme-toggle:focus-visible {\n      outline: 3px solid color-mix(in srgb, var(--blue) 35%, transparent);\n      outline-offset: 3px;\n    }\n\n    .theme-icon {\n      font-size: 0.95rem;\n      line-height: 1;\n    }\n\n    .hero {\n      min-height: 460px;\n      display: grid;\n      grid-template-columns: 1fr 280px;\n      gap: 50px;\n      align-items: center;\n      padding: clamp(42px, 7vw, 82px);\n      border-bottom: 1px solid var(--line);\n    }\n\n    p,\n    h1,\n    h2,\n    h3 {\n      margin-top: 0;\n    }\n\n    .hero-label {\n      margin-bottom: 15px;\n      color: var(--blue);\n      font-size: 0.82rem;\n      font-weight: 800;\n      letter-spacing: 0.16em;\n    }\n\n    h1 {\n      margin-bottom: 10px;\n      color: var(--ink);\n      font-size: clamp(4rem, 10vw, 7.5rem);\n      line-height: 0.94;\n      letter-spacing: -0.08em;\n    }\n\n    .name-en {\n      margin-bottom: 30px;\n      color: var(--muted);\n      font-size: 0.9rem;\n      font-weight: 700;\n      letter-spacing: 0.22em;\n    }\n\n    .job {\n      margin-bottom: 7px;\n      color: var(--ink);\n      font-size: clamp(1.05rem, 2.3vw, 1.35rem);\n      font-weight: 800;\n      word-break: keep-all;\n    }\n\n    .role {\n      margin-bottom: 20px;\n      color: var(--muted);\n      font-size: 0.94rem;\n    }\n\n    .hero-statement {\n      max-width: 610px;\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.2rem, 2.8vw, 1.75rem);\n      font-weight: 700;\n      line-height: 1.5;\n      word-break: keep-all;\n    }\n\n    .portrait {\n      width: 250px;\n      aspect-ratio: 1;\n      display: grid;\n      place-items: center;\n      position: relative;\n      overflow: hidden;\n      justify-self: end;\n      color: var(--paper);\n      background: var(--blue);\n      border-radius: 50%;\n    }\n\n    .portrait::before {\n      content: \"\";\n      position: absolute;\n      inset: 0;\n      background: repeating-linear-gradient(\n        125deg,\n        rgba(255,255,255,.13) 0 2px,\n        transparent 2px 12px\n      );\n    }\n\n    .portrait::after {\n      content: \"\";\n      position: absolute;\n      width: 135px;\n      height: 135px;\n      right: -38px;\n      bottom: -38px;\n      background: rgba(255,255,255,.12);\n      border-radius: 50%;\n    }\n\n    .initials {\n      z-index: 1;\n      font-size: 4.4rem;\n      font-weight: 900;\n      letter-spacing: -0.05em;\n    }\n\n    .plant {\n      position: absolute;\n      right: 18%;\n      bottom: 15%;\n      z-index: 2;\n      font-size: 2.2rem;\n    }\n\n    .content {\n      padding: 0 clamp(28px, 7vw, 82px);\n    }\n\n    .section {\n      display: grid;\n      grid-template-columns: minmax(190px, 28%) 1fr;\n      gap: clamp(30px, 6vw, 74px);\n      padding: clamp(34px, 5vw, 56px) 0;\n      border-bottom: 1px solid var(--line);\n    }\n\n    .section:last-child {\n      border-bottom: 0;\n    }\n\n    .section-index {\n      display: block;\n      margin-bottom: 8px;\n      color: var(--blue);\n      font-size: 0.76rem;\n      font-weight: 800;\n      letter-spacing: 0.12em;\n    }\n\n    h2 {\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.65rem, 3.4vw, 2.5rem);\n      line-height: 1.2;\n      letter-spacing: -0.05em;\n    }\n\n    .section-body {\n      align-self: center;\n    }\n\n    .lead {\n      max-width: 680px;\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.04rem, 2vw, 1.22rem);\n      font-weight: 700;\n      line-height: 1.75;\n      word-break: keep-all;\n    }\n\n    .sub-copy {\n      max-width: 680px;\n      margin: 12px 0 0;\n      color: var(--text);\n      font-size: 0.94rem;\n      word-break: keep-all;\n    }\n\n    .example {\n      display: inline-flex;\n      gap: 10px;\n      align-items: center;\n      margin-top: 20px;\n      padding: 11px 15px;\n      color: #7c5036;\n      background: var(--peach);\n      border-radius: 13px;\n      font-size: 0.9rem;\n      font-weight: 700;\n      transform: rotate(-0.5deg);\n    }\n\n    .example-icon {\n      font-size: 1.45rem;\n    }\n\n    .role-grid,\n    .purpose-grid {\n      display: grid;\n      gap: 12px;\n    }\n\n    .role-grid {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n\n    .purpose-grid {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      margin-top: 18px;\n    }\n\n    .info-card {\n      min-height: 128px;\n      padding: 20px;\n      background: var(--blue-soft);\n      border-radius: 15px;\n    }\n\n    .info-card:nth-child(even) {\n      background: var(--mint);\n    }\n\n    .info-card strong {\n      display: block;\n      margin-bottom: 7px;\n      color: var(--ink);\n      font-size: 1rem;\n    }\n\n    .info-card span {\n      display: block;\n      color: var(--text);\n      font-size: 0.88rem;\n      word-break: keep-all;\n    }\n\n    .purpose-card {\n      padding: 18px;\n      border: 1px solid var(--line);\n      border-top: 4px solid var(--blue);\n      border-radius: 4px 4px 12px 12px;\n    }\n\n    .purpose-card strong {\n      display: block;\n      margin-bottom: 6px;\n      color: var(--ink);\n      font-size: 0.94rem;\n    }\n\n    .purpose-card span {\n      display: block;\n      color: var(--muted);\n      font-size: 0.82rem;\n      word-break: keep-all;\n    }\n\n    .trait-list {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 10px;\n      margin-bottom: 18px;\n    }\n\n    .trait {\n      padding: 7px 12px;\n      color: var(--blue);\n      background: var(--blue-soft);\n      border-radius: 999px;\n      font-size: 0.88rem;\n      font-weight: 800;\n    }\n\n    .interest-layout {\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 24px;\n      align-items: center;\n    }\n\n    .interest-icons {\n      width: 112px;\n      height: 112px;\n      display: grid;\n      place-items: center;\n      background: var(--mint);\n      border-radius: 50%;\n      font-size: 2.25rem;\n      white-space: nowrap;\n    }\n\n    footer {\n      padding: 28px;\n      color: var(--muted);\n      text-align: center;\n      background: color-mix(in srgb, var(--paper) 94%, var(--page));\n      border-top: 1px solid var(--line);\n      font-size: 0.82rem;\n    }\n\n    @media (max-width: 760px) {\n      .page {\n        width: 100%;\n        margin: 0;\n        box-shadow: none;\n      }\n\n      .toolbar {\n        position: fixed;\n        top: 14px;\n        right: 14px;\n        flex-wrap: wrap;\n        justify-content: flex-end;\n        max-width: calc(100% - 28px);\n      }\n\n      .language-switch,\n      .theme-toggle {\n        background: color-mix(in srgb, var(--paper) 92%, transparent);\n        backdrop-filter: blur(8px);\n      }\n\n      .hero {\n        min-height: auto;\n        grid-template-columns: 1fr;\n        gap: 32px;\n        padding: 40px 24px;\n      }\n\n      .portrait {\n        width: 190px;\n        justify-self: start;\n        grid-row: 1;\n      }\n\n      .hero-copy {\n        grid-row: 2;\n      }\n\n      .section {\n        grid-template-columns: 1fr;\n        gap: 20px;\n      }\n\n      .role-grid,\n      .purpose-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .info-card {\n        min-height: auto;\n      }\n    }\n\n    @media (max-width: 460px) {\n      .content {\n        padding: 0 22px;\n      }\n\n      .interest-layout {\n        grid-template-columns: 1fr;\n      }\n\n      .interest-icons {\n        width: 96px;\n        height: 96px;\n      }\n    }\n  </style>\n</head>\n<body>\n  <main class=\"page\">\n    <div class=\"toolbar\">\n      <div class=\"language-switch\" role=\"group\" aria-label=\"언어 선택\">\n        <button class=\"language-button\" type=\"button\" data-lang=\"ko\" aria-pressed=\"true\">한국어</button>\n        <button class=\"language-button\" type=\"button\" data-lang=\"en\" aria-pressed=\"false\">English</button>\n        <button class=\"language-button\" type=\"button\" data-lang=\"ja\" aria-pressed=\"false\">日本語</button>\n        <button class=\"language-button\" type=\"button\" data-lang=\"zh\" aria-pressed=\"false\">中文</button>\n      </div>\n      <button class=\"theme-toggle\" type=\"button\" aria-label=\"다크모드 전환\" aria-pressed=\"false\">\n        <span class=\"theme-icon\" aria-hidden=\"true\">◐</span>\n        <span class=\"theme-label\" data-i18n=\"theme.dark\">다크모드</span>\n      </button>\n    </div>\n\n    <header class=\"hero\">\n      <div class=\"hero-copy\">\n        <p class=\"hero-label\" data-i18n=\"hero.label\">PERSONAL PROFILE</p>\n        <h1 data-i18n=\"hero.name\">이성호</h1>\n        <p class=\"name-en\">LEE SUNG HO</p>\n        <p class=\"job\" data-i18n=\"hero.job\">임베디드 엔지니어 · 전자제품 개발자</p>\n        <p class=\"role\" data-i18n=\"hero.role\">스타트업 개발팀장</p>\n        <p class=\"hero-statement\" data-i18n=\"hero.statement\">생활 속 아이디어를 실제로 움직이는 제품으로 만듭니다.</p>\n      </div>\n\n      <div class=\"portrait\" aria-label=\"이성호 프로필 그래픽\">\n        <span class=\"initials\">SH</span>\n        <span class=\"plant\" aria-hidden=\"true\">🪴</span>\n      </div>\n    </header>\n\n    <div class=\"content\">\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\" data-i18n=\"who.index\">01 · WHO I AM</span>\n          <h2 data-i18n=\"who.title\">어떤 사람인가</h2>\n        </div>\n        <div class=\"section-body\">\n          <p class=\"lead\" data-i18n=\"who.lead\">문제가 생기면 직접 확인하고, 원인을 찾을 때까지 차근차근 살펴봅니다.</p>\n          <p class=\"sub-copy\" data-i18n=\"who.copy\">복잡한 문제는 작은 단위로 나누고 실제 사용 환경에서도 안정적으로 쓸 수 있는 결과를 중요하게 생각합니다.</p>\n          <div class=\"example\"><span class=\"example-icon\" aria-hidden=\"true\">🪴</span><span data-i18n=\"who.example\">목마르면 표정이 바뀌는 화분 같은 아이디어를 좋아합니다.</span></div>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\" data-i18n=\"work.index\">02 · WHAT I DO</span>\n          <h2 data-i18n=\"work.title\">현재 하는 일</h2>\n        </div>\n        <div class=\"section-body role-grid\">\n          <article class=\"info-card\">\n            <strong data-i18n=\"work.idea.title\">아이디어 구체화</strong>\n            <span data-i18n=\"work.idea.copy\">생활 속 생각을 실제로 개발할 수 있는 제품의 모습으로 정리합니다.</span>\n          </article>\n          <article class=\"info-card\">\n            <strong data-i18n=\"work.team.title\">팀과 문제 해결</strong>\n            <span data-i18n=\"work.team.copy\">개발 과정에서 생기는 문제를 팀원들과 확인하고 함께 해결합니다.</span>\n          </article>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\" data-i18n=\"education.index\">03 · WHY I’M HERE</span>\n          <h2 data-i18n=\"education.title\">교육에 참여한 이유</h2>\n        </div>\n        <div class=\"section-body\">\n          <p class=\"lead\" data-i18n=\"education.lead\">바이브코딩을 실제 업무에 활용할 방법을 직접 확인해 보고 싶습니다.</p>\n          <div class=\"purpose-grid\">\n            <div class=\"purpose-card\"><strong data-i18n=\"education.test.title\">테스트용 앱</strong><span data-i18n=\"education.test.copy\">제품 기능과 아이디어 확인</span></div>\n            <div class=\"purpose-card\"><strong data-i18n=\"education.tool.title\">업무 도구</strong><span data-i18n=\"education.tool.copy\">반복적인 개발 업무 줄이기</span></div>\n            <div class=\"purpose-card\"><strong data-i18n=\"education.material.title\">소개 자료</strong><span data-i18n=\"education.material.copy\">회사와 제품을 쉽게 설명하기</span></div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\" data-i18n=\"thinking.index\">04 · HOW I THINK</span>\n          <h2 data-i18n=\"thinking.title\">일하는 방식</h2>\n        </div>\n        <div class=\"section-body\">\n          <div class=\"trait-list\" aria-label=\"나를 표현하는 키워드\">\n            <span class=\"trait\" data-i18n=\"thinking.curiosity\">호기심</span>\n            <span class=\"trait\" data-i18n=\"thinking.persistence\">끈기</span>\n            <span class=\"trait\" data-i18n=\"thinking.practical\">현실적인 문제 해결</span>\n          </div>\n          <p class=\"lead\" data-i18n=\"thinking.lead\">넘겨짚기보다 직접 확인하고, 임시방편보다 실제로 계속 사용할 수 있는 방법을 찾습니다.</p>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\" data-i18n=\"outside.index\">05 · OUTSIDE WORK</span>\n          <h2 data-i18n=\"outside.title\">좋아하는 시간</h2>\n        </div>\n        <div class=\"section-body interest-layout\">\n          <div class=\"interest-icons\" aria-hidden=\"true\">🚗 🎵</div>\n          <p class=\"lead\" data-i18n=\"outside.lead\">그날의 기분에 따라 다양한 음악을 들으며 운전하고, 생각을 정리하는 시간을 좋아합니다.</p>\n        </div>\n      </section>\n    </div>\n\n    <footer data-i18n=\"footer\">교육에서 잘 부탁드립니다.</footer>\n  </main>\n  <script>\n    (() => {\n      const root = document.documentElement;\n      const themeButton = document.querySelector(\".theme-toggle\");\n      const themeLabel = document.querySelector(\".theme-label\");\n      const languageSwitch = document.querySelector(\".language-switch\");\n      const languageButtons = document.querySelectorAll(\".language-button\");\n      const traitList = document.querySelector(\".trait-list\");\n\n      const translations = {\n        ko: {\n          \"page.title\": \"이성호 | 자기소개\",\n          \"language.label\": \"언어 선택\",\n          \"theme.toggle\": \"화면 테마 전환\",\n          \"theme.dark\": \"다크모드\",\n          \"theme.light\": \"라이트모드\",\n          \"traits.label\": \"나를 표현하는 키워드\",\n          \"hero.label\": \"개인 소개\",\n          \"hero.name\": \"이성호\",\n          \"hero.job\": \"임베디드 엔지니어 · 전자제품 개발자\",\n          \"hero.role\": \"스타트업 개발팀장\",\n          \"hero.statement\": \"생활 속 아이디어를 실제로 움직이는 제품으로 만듭니다.\",\n          \"who.index\": \"01 · WHO I AM\",\n          \"who.title\": \"어떤 사람인가\",\n          \"who.lead\": \"문제가 생기면 직접 확인하고, 원인을 찾을 때까지 차근차근 살펴봅니다.\",\n          \"who.copy\": \"복잡한 문제는 작은 단위로 나누고 실제 사용 환경에서도 안정적으로 쓸 수 있는 결과를 중요하게 생각합니다.\",\n          \"who.example\": \"목마르면 표정이 바뀌는 화분 같은 아이디어를 좋아합니다.\",\n          \"work.index\": \"02 · WHAT I DO\",\n          \"work.title\": \"현재 하는 일\",\n          \"work.idea.title\": \"아이디어 구체화\",\n          \"work.idea.copy\": \"생활 속 생각을 실제로 개발할 수 있는 제품의 모습으로 정리합니다.\",\n          \"work.team.title\": \"팀과 문제 해결\",\n          \"work.team.copy\": \"개발 과정에서 생기는 문제를 팀원들과 확인하고 함께 해결합니다.\",\n          \"education.index\": \"03 · WHY I’M HERE\",\n          \"education.title\": \"교육에 참여한 이유\",\n          \"education.lead\": \"바이브코딩을 실제 업무에 활용할 방법을 직접 확인해 보고 싶습니다.\",\n          \"education.test.title\": \"테스트용 앱\",\n          \"education.test.copy\": \"제품 기능과 아이디어 확인\",\n          \"education.tool.title\": \"업무 도구\",\n          \"education.tool.copy\": \"반복적인 개발 업무 줄이기\",\n          \"education.material.title\": \"소개 자료\",\n          \"education.material.copy\": \"회사와 제품을 쉽게 설명하기\",\n          \"thinking.index\": \"04 · HOW I THINK\",\n          \"thinking.title\": \"일하는 방식\",\n          \"thinking.curiosity\": \"호기심\",\n          \"thinking.persistence\": \"끈기\",\n          \"thinking.practical\": \"현실적인 문제 해결\",\n          \"thinking.lead\": \"넘겨짚기보다 직접 확인하고, 임시방편보다 실제로 계속 사용할 수 있는 방법을 찾습니다.\",\n          \"outside.index\": \"05 · OUTSIDE WORK\",\n          \"outside.title\": \"좋아하는 시간\",\n          \"outside.lead\": \"그날의 기분에 따라 다양한 음악을 들으며 운전하고, 생각을 정리하는 시간을 좋아합니다.\",\n          \"footer\": \"교육에서 잘 부탁드립니다.\"\n        },\n        en: {\n          \"page.title\": \"Sung Ho Lee | Profile\",\n          \"language.label\": \"Select language\",\n          \"theme.toggle\": \"Switch display theme\",\n          \"theme.dark\": \"Dark\",\n          \"theme.light\": \"Light\",\n          \"traits.label\": \"Keywords that describe me\",\n          \"hero.label\": \"PERSONAL PROFILE\",\n          \"hero.name\": \"Sung Ho Lee\",\n          \"hero.job\": \"Embedded Engineer · Electronics Product Developer\",\n          \"hero.role\": \"Development Team Lead at a Startup\",\n          \"hero.statement\": \"I turn everyday ideas into products that work in the real world.\",\n          \"who.index\": \"01 · WHO I AM\",\n          \"who.title\": \"Who I am\",\n          \"who.lead\": \"When a problem appears, I check it myself and work through it until I find the cause.\",\n          \"who.copy\": \"I break complex problems into smaller parts and value results that remain reliable in real-world use.\",\n          \"who.example\": \"I like ideas such as a plant pot whose expression changes when it needs water.\",\n          \"work.index\": \"02 · WHAT I DO\",\n          \"work.title\": \"What I do\",\n          \"work.idea.title\": \"Shape ideas\",\n          \"work.idea.copy\": \"I turn everyday thoughts into product concepts that can actually be developed.\",\n          \"work.team.title\": \"Solve problems together\",\n          \"work.team.copy\": \"I investigate issues during development and solve them with my team.\",\n          \"education.index\": \"03 · WHY I’M HERE\",\n          \"education.title\": \"Why I joined\",\n          \"education.lead\": \"I want to test practical ways to use vibe coding in my day-to-day work.\",\n          \"education.test.title\": \"Test apps\",\n          \"education.test.copy\": \"Check product functions and ideas\",\n          \"education.tool.title\": \"Work tools\",\n          \"education.tool.copy\": \"Reduce repetitive development tasks\",\n          \"education.material.title\": \"Intro materials\",\n          \"education.material.copy\": \"Explain the company and products clearly\",\n          \"thinking.index\": \"04 · HOW I THINK\",\n          \"thinking.title\": \"How I work\",\n          \"thinking.curiosity\": \"Curiosity\",\n          \"thinking.persistence\": \"Persistence\",\n          \"thinking.practical\": \"Practical problem solving\",\n          \"thinking.lead\": \"I prefer checking things directly over guessing, and lasting solutions over temporary fixes.\",\n          \"outside.index\": \"05 · OUTSIDE WORK\",\n          \"outside.title\": \"What I enjoy\",\n          \"outside.lead\": \"I enjoy driving, listening to different kinds of music, and using that time to organize my thoughts.\",\n          \"footer\": \"I look forward to taking part in the program.\"\n        },\n        ja: {\n          \"page.title\": \"イ・ソンホ | 自己紹介\",\n          \"language.label\": \"言語を選択\",\n          \"theme.toggle\": \"表示テーマを切り替える\",\n          \"theme.dark\": \"ダーク\",\n          \"theme.light\": \"ライト\",\n          \"traits.label\": \"自分を表すキーワード\",\n          \"hero.label\": \"自己紹介\",\n          \"hero.name\": \"イ・ソンホ\",\n          \"hero.job\": \"組み込みエンジニア・電子製品開発者\",\n          \"hero.role\": \"スタートアップ開発チームリーダー\",\n          \"hero.statement\": \"日常のアイデアを、実際に動く製品へと形にします。\",\n          \"who.index\": \"01 · WHO I AM\",\n          \"who.title\": \"どんな人か\",\n          \"who.lead\": \"問題が起きたら自分で確認し、原因が見つかるまで一つずつ調べます。\",\n          \"who.copy\": \"複雑な問題は小さく分け、実際の使用環境でも安定して使える結果を大切にしています。\",\n          \"who.example\": \"水が必要になると表情が変わる植木鉢のようなアイデアが好きです。\",\n          \"work.index\": \"02 · WHAT I DO\",\n          \"work.title\": \"現在の仕事\",\n          \"work.idea.title\": \"アイデアを具体化\",\n          \"work.idea.copy\": \"日常の発想を、実際に開発できる製品の形に整理します。\",\n          \"work.team.title\": \"チームで問題解決\",\n          \"work.team.copy\": \"開発中に起きる問題をチームで確認し、一緒に解決します。\",\n          \"education.index\": \"03 · WHY I’M HERE\",\n          \"education.title\": \"研修に参加した理由\",\n          \"education.lead\": \"バイブコーディングを実務で活用する方法を、自分で試して確かめたいと考えています。\",\n          \"education.test.title\": \"テスト用アプリ\",\n          \"education.test.copy\": \"製品機能とアイデアの確認\",\n          \"education.tool.title\": \"業務ツール\",\n          \"education.tool.copy\": \"繰り返し作業の削減\",\n          \"education.material.title\": \"紹介資料\",\n          \"education.material.copy\": \"会社と製品を分かりやすく説明\",\n          \"thinking.index\": \"04 · HOW I THINK\",\n          \"thinking.title\": \"仕事の進め方\",\n          \"thinking.curiosity\": \"好奇心\",\n          \"thinking.persistence\": \"粘り強さ\",\n          \"thinking.practical\": \"現実的な問題解決\",\n          \"thinking.lead\": \"推測よりも自分で確認すること、一時的な対応よりも継続して使える方法を重視します。\",\n          \"outside.index\": \"05 · OUTSIDE WORK\",\n          \"outside.title\": \"好きな時間\",\n          \"outside.lead\": \"その日の気分に合うさまざまな音楽を聴きながら運転し、考えを整理する時間が好きです。\",\n          \"footer\": \"研修ではよろしくお願いします。\"\n        },\n        zh: {\n          \"page.title\": \"LEE SUNG HO | 个人介绍\",\n          \"language.label\": \"选择语言\",\n          \"theme.toggle\": \"切换显示主题\",\n          \"theme.dark\": \"深色\",\n          \"theme.light\": \"浅色\",\n          \"traits.label\": \"描述我的关键词\",\n          \"hero.label\": \"个人介绍\",\n          \"hero.name\": \"LEE SUNG HO\",\n          \"hero.job\": \"嵌入式工程师 · 电子产品开发者\",\n          \"hero.role\": \"初创企业开发团队负责人\",\n          \"hero.statement\": \"把日常生活中的想法变成真正能够运行的产品。\",\n          \"who.index\": \"01 · WHO I AM\",\n          \"who.title\": \"我是怎样的人\",\n          \"who.lead\": \"遇到问题时，我会亲自确认，并一步步查找到真正的原因。\",\n          \"who.copy\": \"我会把复杂问题拆分成较小的部分，并重视在实际使用环境中也能稳定工作的结果。\",\n          \"who.example\": \"我喜欢“缺水时表情会变化的花盆”这类有趣的产品想法。\",\n          \"work.index\": \"02 · WHAT I DO\",\n          \"work.title\": \"目前的工作\",\n          \"work.idea.title\": \"把想法具体化\",\n          \"work.idea.copy\": \"把生活中的想法整理成能够实际开发的产品方案。\",\n          \"work.team.title\": \"与团队解决问题\",\n          \"work.team.copy\": \"与团队一起确认并解决开发过程中出现的问题。\",\n          \"education.index\": \"03 · WHY I’M HERE\",\n          \"education.title\": \"参加培训的原因\",\n          \"education.lead\": \"我想亲自验证如何把氛围编程实际应用到日常工作中。\",\n          \"education.test.title\": \"测试应用\",\n          \"education.test.copy\": \"验证产品功能和想法\",\n          \"education.tool.title\": \"工作工具\",\n          \"education.tool.copy\": \"减少重复的开发工作\",\n          \"education.material.title\": \"介绍资料\",\n          \"education.material.copy\": \"清楚介绍公司和产品\",\n          \"thinking.index\": \"04 · HOW I THINK\",\n          \"thinking.title\": \"工作方式\",\n          \"thinking.curiosity\": \"好奇心\",\n          \"thinking.persistence\": \"坚持\",\n          \"thinking.practical\": \"务实地解决问题\",\n          \"thinking.lead\": \"比起猜测，我更愿意亲自确认；比起临时处理，我更重视能够长期使用的方法。\",\n          \"outside.index\": \"05 · OUTSIDE WORK\",\n          \"outside.title\": \"喜欢的时光\",\n          \"outside.lead\": \"我喜欢一边开车一边听不同类型的音乐，也会利用这段时间整理思绪。\",\n          \"footer\": \"期待参加这次培训。\"\n        }\n      };\n\n      let currentLanguage = localStorage.getItem(\"profile-language\") || \"ko\";\n\n      const updateThemeLabel = () => {\n        const dictionary = translations[currentLanguage];\n        const isDark = root.dataset.theme === \"dark\";\n        themeLabel.textContent = isDark ? dictionary[\"theme.light\"] : dictionary[\"theme.dark\"];\n        themeButton.setAttribute(\"aria-label\", dictionary[\"theme.toggle\"]);\n      };\n\n      const applyTheme = (theme) => {\n        const isDark = theme === \"dark\";\n        root.dataset.theme = theme;\n        themeButton.setAttribute(\"aria-pressed\", String(isDark));\n        updateThemeLabel();\n      };\n\n      const applyLanguage = (language) => {\n        currentLanguage = translations[language] ? language : \"ko\";\n        const dictionary = translations[currentLanguage];\n\n        root.lang = currentLanguage === \"zh\" ? \"zh-CN\" : currentLanguage;\n        document.title = dictionary[\"page.title\"];\n        languageSwitch.setAttribute(\"aria-label\", dictionary[\"language.label\"]);\n        traitList.setAttribute(\"aria-label\", dictionary[\"traits.label\"]);\n\n        document.querySelectorAll(\"[data-i18n]\").forEach((element) => {\n          const translated = dictionary[element.dataset.i18n];\n          if (translated) {\n            element.textContent = translated;\n          }\n        });\n\n        languageButtons.forEach((languageButton) => {\n          languageButton.setAttribute(\n            \"aria-pressed\",\n            String(languageButton.dataset.lang === currentLanguage)\n          );\n        });\n\n        updateThemeLabel();\n      };\n\n      applyLanguage(currentLanguage);\n      applyTheme(root.dataset.theme);\n\n      languageButtons.forEach((languageButton) => {\n        languageButton.addEventListener(\"click\", () => {\n          const selectedLanguage = languageButton.dataset.lang;\n          localStorage.setItem(\"profile-language\", selectedLanguage);\n          applyLanguage(selectedLanguage);\n        });\n      });\n\n      themeButton.addEventListener(\"click\", () => {\n        const nextTheme = root.dataset.theme === \"dark\" ? \"light\" : \"dark\";\n        localStorage.setItem(\"profile-theme\", nextTheme);\n        applyTheme(nextTheme);\n      });\n    })();\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not Found", { status: 404 });
    }

    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "public, max-age=300"
      }
    });
  }
};
